wfmExport=wfmExportFixed;
async function wfmPublishWeekSafe(){if(wfmState.busy)return;const week=wfmWeekInfo(wfmState.date);if(wfmState.dirty){if(!confirm('Tenés cambios sin guardar en el borrador de hoy. ¿Guardarlos antes de publicar la semana?'))return;if(!await wfmSend('save'))return}wfmState.busy=true;wfmPaint();try{const dates=Array.from({length:7},(_,i)=>wfmShiftDate(week.start,i)),expected_revisions={},details=[],plans=await Promise.all(dates.map(date=>api('/api/wfm/plan?date='+date+'&team='+encodeURIComponent(wfmState.team))));plans.forEach((plan,index)=>{const date=dates[index];expected_revisions[date]=plan.revision||0;const status=plan.revision===plan.published_revision?'ya publicada':plan.revision?'borrador listo':'sin borrador';const warnings=(plan.warnings||[]).map(item=>'⚠ '+item).join(' · ');details.push(wfmDateLabel(date)+' · revisión '+(plan.revision||0)+' · '+status+(warnings?' · '+warnings:''))});if(!confirm('¿Publicar la semana '+week.week+'?\n\n'+details.join('\n')))return;const result=await api('/api/wfm/publish-week?week='+week.start+'&team='+encodeURIComponent(wfmState.team),{method:'POST',body:JSON.stringify({confirm_exceptions:true,expected_revisions})}),parts=[result.published_count+' día'+(result.published_count===1?'':'s')+' publicado'+(result.published_count===1?'':'s')];if(result.already_published.length)parts.push(result.already_published.length+' ya publicados');if(result.missing_drafts.length)parts.push(result.missing_drafts.length+' sin borrador');if(result.warnings?.length)parts.push(result.warnings.length+' advertencias confirmadas');toast(parts.join(' · '));await wfmLoad()}catch(error){toast(error.message)}finally{wfmState.busy=false;if(wfmState.plan)wfmPaint()}}
