function wfmNormalizePlan(plan){const horizon=+plan.horizon||72,window=Array.isArray(plan.window)?{start:+plan.window[0],end:+plan.window[1]}:WFM_TEAM_WINDOWS[wfmState.team];plan.demand=Array.from({length:horizon},(_,slot)=>plan.demand?.[slot]??(slot>=window.start&&slot<window.end?wfmRequirementForSlot(plan,slot):0));plan.shifts=(plan.shifts||[]).map(shift=>{const segments=wfmSegments(shift).map(s=>({start:+s.start,end:+s.end})).sort((a,b)=>a.start-b.start);return {...shift,start:segments[0].start,end:segments.at(-1).end,segments,exceptions:Array.isArray(shift.exceptions)?shift.exceptions:[],break_duration:shift.break_duration??1,overtime_slots:shift.overtime_slots??0}});return plan}
