async function wfmLoad(){const plan=await api(`/api/wfm/plan?date=${wfmState.date}&team=${encodeURIComponent(wfmState.team)}`),requestParams=new URLSearchParams({team:wfmState.team});if(wfmState.requestStatus!=='TODAS')requestParams.set('status',wfmState.requestStatus);if(wfmState.requestType)requestParams.set('request_type',wfmState.requestType);if(wfmState.requestDate){requestParams.set('date_from',wfmState.requestDate);requestParams.set('date_to',wfmState.requestDate)}if(wfmState.requestSearch)requestParams.set('q',wfmState.requestSearch);let requests=[];try{requests=await api(`/api/wfm/requests?${requestParams}`)}catch(error){console.warn('No se pudo cargar la bandeja WFM:',error.message)}plan.requirements=wfmRequirements(plan);wfmState.plan=wfmNormalizePlan(plan);wfmState.requests=requests;wfmState.dirty=false;wfmPaint()}
